{
  "framing": {
    "libro": "Propaganda",
    "autor": "Edward Bernays",
    "año": 1928,
    "cita_breve": "«The conscious and intelligent manipulation of the organized habits and opinions of the masses is an important element in democratic societies.»",
    "explicacion": "Bernays describe cómo los comunicadores estructuran la presentación de los hechos (marcos o \"frames\") para dirigir la interpretación del público y moldear la opinión colectiva."
  },
  "anclaje": {
    "libro": "Psicología de las Masas",
    "autor": "Gustave Le Bon",
    "año": 1895,
    "cita_breve": "«Las masas son más receptivas a ideas simples, repetidas frecuentemente, y tienden a fijarse en ellas como verdades incontrovertibles.»",
    "explicacion": "Le Bon muestra que la primera información recibida funciona como un ancla cognitiva; los individuos posteriores ajustan sus juicios respecto a ese punto de referencia."
  },
  "omision": {
    "libro": "Manufacturing Consent",
    "autor": "Noam Chomsky & Edward S. Herman",
    "año": 1988,
    "cita_breve": "«Lo que los medios no dicen es tan importante como lo que dicen.»",
    "explicacion": "Chomsky y Herman explican que la selección de temas excluidos constituye una forma de control ideológico, pues la omisión de información limita el debate público."
  }
}
